validator:
function validate(input) {
  const [{ employees = [] }] = input;
  const boss = new Map();
  let ceos = 0;
  for (const [id, name, manager, salary] of employees) {
    if (id === null || name === null || salary === null) return 'employee_id, employee_name and salary may not be null.';
    if (boss.has(id)) return `employee_id ${id} appears twice.`;
    if (salary <= 0) return `Employee ${id} needs a positive salary.`;
    if (manager === null) ceos++;
    boss.set(id, manager);
  }
  if (employees.length && ceos !== 1) return 'Exactly one employee must have a null manager_id.';
  for (const [id, manager] of boss) if (manager !== null && !boss.has(manager)) return `Employee ${id} has a manager_id that is not an employee.`;
  for (const id of boss.keys()) {
    let at = id, steps = 0;
    while (at !== null && steps <= boss.size) { at = boss.get(at); steps++; }
    if (at !== null) return `Employee ${id} is in a management cycle.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const names = ['Alice', 'Bob', 'Charlie', 'David', 'Eve', 'Frank', 'Grace', 'Helen', 'Ivan', 'Judy'];
  const small = size === 'small';
  const count = small ? pick(9) : 2000;
  const pool = small ? [1, 2, 3, 4, 5, 6, 7, 8, 9, 12, 20, 31] : Array.from({ length: 3000 }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) { const j = pick(i + 1); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const pay = [90000, 95000, 100000, 120000, 150000];
  const salary = () => (small ? pay[pick(pay.length)] : 30000 + 1000 * pick(171));
  const rows = [];
  // The first employee is the CEO; each later one reports to someone already placed,
  // often the newest one so that chains get deep.
  for (let i = 0; i < count; i++) {
    const manager = i === 0 ? null : rows[rand() < 0.3 ? i - 1 : pick(i)][0];
    rows.push([pool[i], names[pick(names.length)], manager, salary()]);
  }
  for (let i = rows.length - 1; i > 0; i--) { const j = pick(i + 1); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  return [{ employees: rows }];
}
